		/// <summary>
		/// Lets you efficiently bulk insert many entities to the database.
		/// </summary>
		/// <param name="transactionManager">The transaction manager.</param>
		/// <param name="entities">The entities.</param>
		/// <remarks>
		///		After inserting into the datasource, the MAT.Entities.Servicio object will be updated
		/// 	to refelect any changes made by the datasource. (ie: identity or computed columns)
		/// </remarks>	
		public override void BulkInsert(TransactionManager transactionManager, TList<MAT.Entities.Servicio> entities)
		{
			//System.Data.SqlClient.SqlBulkCopy bulkCopy = new System.Data.SqlClient.SqlBulkCopy(this._connectionString, System.Data.SqlClient.SqlBulkCopyOptions.CheckConstraints); //, null);
			
			System.Data.SqlClient.SqlBulkCopy bulkCopy = null;
	
			if (transactionManager != null && transactionManager.IsOpen)
			{			
				System.Data.SqlClient.SqlConnection cnx = transactionManager.TransactionObject.Connection as System.Data.SqlClient.SqlConnection;
				System.Data.SqlClient.SqlTransaction transaction = transactionManager.TransactionObject as System.Data.SqlClient.SqlTransaction;
				bulkCopy = new System.Data.SqlClient.SqlBulkCopy(cnx, System.Data.SqlClient.SqlBulkCopyOptions.CheckConstraints, transaction); //, null);
			}
			else
			{
				bulkCopy = new System.Data.SqlClient.SqlBulkCopy(this._connectionString, System.Data.SqlClient.SqlBulkCopyOptions.CheckConstraints); //, null);
			}
			
			bulkCopy.BulkCopyTimeout = 360;
			bulkCopy.DestinationTableName = "Servicio";
			
			DataTable dataTable = new DataTable();
			DataColumn col0 = dataTable.Columns.Add("ServicioID", typeof(System.Guid));
			col0.AllowDBNull = false;		
			DataColumn col1 = dataTable.Columns.Add("Descripcion", typeof(System.String));
			col1.AllowDBNull = false;		
			DataColumn col2 = dataTable.Columns.Add("Precio", typeof(System.Double));
			col2.AllowDBNull = true;		
			DataColumn col3 = dataTable.Columns.Add("Moneda", typeof(System.String));
			col3.AllowDBNull = true;		
			DataColumn col4 = dataTable.Columns.Add("Iva", typeof(System.String));
			col4.AllowDBNull = true;		
			DataColumn col5 = dataTable.Columns.Add("Alicuota", typeof(System.Double));
			col5.AllowDBNull = true;		
			DataColumn col6 = dataTable.Columns.Add("Validez", typeof(System.DateTime));
			col6.AllowDBNull = true;		
			DataColumn col7 = dataTable.Columns.Add("VisibilidadTarifa", typeof(System.Int32));
			col7.AllowDBNull = true;		
			DataColumn col8 = dataTable.Columns.Add("ProveedorID", typeof(System.Guid));
			col8.AllowDBNull = true;		
			DataColumn col9 = dataTable.Columns.Add("TransporteID", typeof(System.Guid));
			col9.AllowDBNull = true;		
			DataColumn col10 = dataTable.Columns.Add("HotelID", typeof(System.Guid));
			col10.AllowDBNull = true;		
			DataColumn col11 = dataTable.Columns.Add("TipoServicio", typeof(System.Int32));
			col11.AllowDBNull = true;		
			
			bulkCopy.ColumnMappings.Add("ServicioID", "ServicioID");
			bulkCopy.ColumnMappings.Add("Descripcion", "Descripcion");
			bulkCopy.ColumnMappings.Add("Precio", "Precio");
			bulkCopy.ColumnMappings.Add("Moneda", "Moneda");
			bulkCopy.ColumnMappings.Add("Iva", "Iva");
			bulkCopy.ColumnMappings.Add("Alicuota", "Alicuota");
			bulkCopy.ColumnMappings.Add("Validez", "Validez");
			bulkCopy.ColumnMappings.Add("VisibilidadTarifa", "VisibilidadTarifa");
			bulkCopy.ColumnMappings.Add("ProveedorID", "ProveedorID");
			bulkCopy.ColumnMappings.Add("TransporteID", "TransporteID");
			bulkCopy.ColumnMappings.Add("HotelID", "HotelID");
			bulkCopy.ColumnMappings.Add("TipoServicio", "TipoServicio");
			
			foreach(MAT.Entities.Servicio entity in entities)
			{
				if (entity.EntityState != EntityState.Added)
					continue;
					
				DataRow row = dataTable.NewRow();
				
					row["ServicioID"] = entity.ServicioId;
							
				
					row["Descripcion"] = entity.Descripcion;
							
				
					row["Precio"] = entity.Precio.HasValue ? (object) entity.Precio  : System.DBNull.Value;
							
				
					row["Moneda"] = entity.Moneda;
							
				
					row["Iva"] = entity.Iva;
							
				
					row["Alicuota"] = entity.Alicuota.HasValue ? (object) entity.Alicuota  : System.DBNull.Value;
							
				
					row["Validez"] = entity.Validez.HasValue ? (object) entity.Validez  : System.DBNull.Value;
							
				
					row["VisibilidadTarifa"] = entity.VisibilidadTarifa.HasValue ? (object) entity.VisibilidadTarifa  : System.DBNull.Value;
							
				
					row["ProveedorID"] = entity.ProveedorId.HasValue ? (object) entity.ProveedorId  : System.DBNull.Value;
							
				
					row["TransporteID"] = entity.TransporteId.HasValue ? (object) entity.TransporteId  : System.DBNull.Value;
							
				
					row["HotelID"] = entity.HotelId.HasValue ? (object) entity.HotelId  : System.DBNull.Value;
							
				
					row["TipoServicio"] = entity.TipoServicio.HasValue ? (object) entity.TipoServicio  : System.DBNull.Value;
							
				
				dataTable.Rows.Add(row);
			}		
			
			// send the data to the server		
			bulkCopy.WriteToServer(dataTable);		
			
			// update back the state
			foreach(MAT.Entities.Servicio entity in entities)
			{
				if (entity.EntityState != EntityState.Added)
					continue;
			
				entity.AcceptChanges();
			}
		}
				
